import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import type { PerpsMarketData } from '@metamask/perps-controller';
import { hasVolume, parseVolume } from '../../../components/app/perps/utils';
import { usePerpsStreamManager } from './usePerpsStreamManager';

/**
 * Options for usePerpsLiveMarketData hook
 */
export type UsePerpsLiveMarketDataOptions = {
  /**
   * Whether to auto-fetch on mount.
   *
   * @default true
   */
  autoSubscribe?: boolean;
};

/**
 * Return type for usePerpsLiveMarketData hook
 */
export type UsePerpsLiveMarketDataReturn = {
  /**
   * All market data
   */
  markets: PerpsMarketData[];

  /**
   * Crypto markets only (no marketSource)
   */
  cryptoMarkets: PerpsMarketData[];

  /**
   * HIP-3 markets only (has marketSource)
   */
  hip3Markets: PerpsMarketData[];

  /**
   * Whether the initial data is being loaded
   */
  isInitialLoading: boolean;

  /**
   * Error if fetch failed
   */
  error: Error | null;

  /**
   * Manually refresh market data
   */
  refresh: () => void;
};

// Stable empty array reference
const EMPTY_MARKETS: PerpsMarketData[] = [];

/**
 * Hook for fetching market data with prices.
 *
 * Uses the PerpsStreamManager for cached, BehaviorSubject-like access.
 * Cached data is delivered immediately on subscribe, eliminating loading
 * skeletons when navigating between Perps views.
 *
 * @param options - Hook options
 * @returns Market data and loading state
 * @example
 * ```tsx
 * const { cryptoMarkets, hip3Markets, isInitialLoading } = usePerpsLiveMarketData();
 *
 * if (isInitialLoading) {
 *   return <Loading />;
 * }
 *
 * return (
 *   <>
 *     <MarketList markets={cryptoMarkets} title="Crypto" />
 *     <MarketList markets={hip3Markets} title="Stocks & Commodities" />
 *   </>
 * );
 * ```
 */
export function usePerpsLiveMarketData(
  options: UsePerpsLiveMarketDataOptions = {},
): UsePerpsLiveMarketDataReturn {
  const { autoSubscribe = true } = options;
  const { streamManager, isInitializing } = usePerpsStreamManager();

  // Initialize state from cache if available (synchronous)
  const [markets, setMarkets] = useState<PerpsMarketData[]>(() => {
    if (streamManager) {
      return streamManager.markets.getCachedData();
    }
    return EMPTY_MARKETS;
  });

  const [error, setError] = useState<Error | null>(null);

  // Track whether we've received real data. Seed from cache so the subscribe
  // callback does not re-enter loading after a warm cache hit — without writing
  // a ref inside the useState initializer (react-hooks/refs).
  const hasReceivedData = useRef(
    Boolean(autoSubscribe && streamManager?.markets.hasCachedData()),
  );
  const [isInitialLoading, setIsInitialLoading] = useState(() => {
    // No subscription ⇒ nothing to wait for (avoid setState-in-effect for this).
    if (!autoSubscribe) {
      return false;
    }
    return !streamManager?.markets.hasCachedData();
  });

  const compareByVolumeDesc = useCallback(
    (a: PerpsMarketData, b: PerpsMarketData) =>
      parseVolume(b.volume) - parseVolume(a.volume),
    [],
  );

  // Filter out markets with no trading volume (inactive/delisted)
  const activeMarkets = useMemo(() => {
    return markets.filter(hasVolume).sort(compareByVolumeDesc);
  }, [markets, compareByVolumeDesc]);

  // Derive crypto and HIP-3 markets from active markets, sorted by 24h volume descending
  const cryptoMarkets = useMemo(
    () => activeMarkets.filter((m) => !m.marketSource),
    [activeMarkets],
  );
  const hip3Markets = useMemo(
    () => activeMarkets.filter((m) => m.marketSource),
    [activeMarkets],
  );

  // Manual refresh function
  const refresh = useCallback(() => {
    if (!streamManager) {
      return;
    }
    streamManager.markets.refresh();
  }, [streamManager]);

  const [prevAutoSubscribe, setPrevAutoSubscribe] = useState(autoSubscribe);
  if (autoSubscribe !== prevAutoSubscribe) {
    setPrevAutoSubscribe(autoSubscribe);
    if (autoSubscribe) {
      // false → true: re-enter loading unless cache can satisfy immediately.
      setIsInitialLoading(!streamManager?.markets.hasCachedData());
    } else {
      setIsInitialLoading(false);
    }
  }

  useEffect(() => {
    // If still initializing stream manager, stay in loading state
    if (isInitializing || !streamManager) {
      return;
    }

    if (!autoSubscribe) {
      return;
    }

    // Align with render-time loading when autoSubscribe turns on (Copilot):
    // warm cache ⇒ already "received"; cold ⇒ wait for first callback.
    hasReceivedData.current = streamManager.markets.hasCachedData();

    // Subscribe - callback fires immediately with cached data (if any)
    const unsubscribe = streamManager.markets.subscribe((newMarkets) => {
      if (!hasReceivedData.current) {
        hasReceivedData.current = true;
        setIsInitialLoading(false);
      }

      setMarkets(newMarkets);
      setError(null);
    });

    return () => {
      unsubscribe();
    };
  }, [streamManager, isInitializing, autoSubscribe]);

  // If stream manager isn't ready yet, show loading
  if (!streamManager || isInitializing) {
    return {
      markets: EMPTY_MARKETS,
      cryptoMarkets: EMPTY_MARKETS,
      hip3Markets: EMPTY_MARKETS,
      isInitialLoading: true,
      error: null,
      refresh,
    };
  }

  return {
    markets: activeMarkets,
    cryptoMarkets,
    hip3Markets,
    isInitialLoading,
    error,
    refresh,
  };
}
