/**
 * PerpsStreamManager - Module-level singleton for Perps data caching
 *
 * This manager provides:
 * - Cached channels for positions, orders, account, and markets
 * - BehaviorSubject-like subscription (immediate callback with cached data)
 * - Prewarm functionality to keep cache fresh
 * - Account-aware initialization (reinitializes on account switch)
 * - Optimistic TP/SL overrides (preserves user-set values until WebSocket catches up)
 *
 * Architecture:
 * - Single instance shared across all Perps views (tab, home, detail, etc.)
 * - Cache persists across navigation within Perps
 * - Cache clears on account/network change
 *
 * Usage:
 * ```typescript
 * const streamManager = getPerpsStreamManager();
 * await streamManager.init(selectedAddress);
 *
 * // Subscribe with immediate cached data
 * const unsubscribe = streamManager.positions.subscribe((positions) => {
 *   setPositions(positions);
 * });
 * ```
 */

import type {
  Position,
  Order,
  AccountState,
  OrderFill,
  PerpsMarketData,
  PriceUpdate,
  OrderBookData,
  CandleData,
  CandlePeriod,
} from '@metamask/perps-controller';
import {
  trace,
  endTrace,
  TraceName,
  TraceOperation,
  getPerformanceTimestamp,
} from '../../../shared/lib/trace';
import {
  readPerpsLifecycleContext,
  PERPS_LIFECYCLE_TAG,
} from '../../helpers/perps/entry-trace';
import { submitRequestToBackground } from '../../store/background-connection';
import { clearAllCoalescedRequests } from '../../hooks/perps/coalesceBackgroundRequest';
import {
  clearPerpsMarketFillsModuleCache,
  clearPerpsMarketInfoModuleCache,
} from './perps-cache';
import { CandleStreamChannel } from './CandleStreamChannel';
import { PerpsDataChannel } from './PerpsDataChannel';

/**
 * Health of the dedicated order-book aggregated socket, pushed from the
 * background bridge on the `orderBookAggregatedStatus` channel.
 * - `connecting`: opening or transiently reconnecting.
 * - `connected`: subscription is live.
 * - `error`: dropped and auto-reconnection exhausted; needs a manual reconnect.
 */
export type OrderBookConnectionStatus = 'connecting' | 'connected' | 'error';

/** Why a wallet preload span ended. */
type PreloadEndReason =
  | 'connection_failed'
  | 'released'
  | 'subscriptions_ready'
  | 'timeout';

// Empty array constants for stable references
const EMPTY_POSITIONS: Position[] = [];
const EMPTY_ORDERS: Order[] = [];
const EMPTY_FILLS: OrderFill[] = [];
const EMPTY_MARKETS: PerpsMarketData[] = [];
const EMPTY_PRICES: PriceUpdate[] = [];
const CONNECTION_TIMEOUT_MS = 30_000;
const START_BOUNDARY_TAG = 'start_boundary';
const COMPLETION_BOUNDARY_TAG = 'completion_boundary';
const TESTNET_TAG = 'is_testnet';

/**
 * Placeholder noop function for channel initialization.
 * Actual connect functions are set when init() is called.
 */
// eslint-disable-next-line no-empty-function
const placeholderConnectFn = () => () => {};

/**
 * Optimistic TP/SL override for a position.
 * Used to preserve user-set values until WebSocket catches up.
 */
type OptimisticTPSLOverride = {
  takeProfitPrice?: string;
  stopLossPrice?: string;
  expiresAt: number;
};

// Grace period before falling back to REST.
// Gives the WebSocket time to deliver fresh data on reload, avoiding
// redundant REST calls that contribute to 429 rate-limit errors.
// If no WS data arrives within this window, the REST fallback fires.
const WS_GRACE_PERIOD_MS = 3000;

// Grace period for optimistic overrides (30 seconds)
// HyperLiquid's WebSocket can take >10s to reflect new TP/SL trigger orders
const OPTIMISTIC_OVERRIDE_TTL_MS = 30000;

// Block period: ignore WebSocket pushes for this long after optimistic update
// Prevents immediate overwrite from stale WebSocket data
const WEBSOCKET_BLOCK_MS = 3000;

class PerpsStreamManager {
  // Data channels
  positions: PerpsDataChannel<Position[]>;

  orders: PerpsDataChannel<Order[]>;

  account: PerpsDataChannel<AccountState | null>;

  /** Live order fills — pushed from background via subscribeToOrderFills */
  fills: PerpsDataChannel<OrderFill[]>;

  markets: PerpsDataChannel<PerpsMarketData[]>;

  prices: PerpsDataChannel<PriceUpdate[]>;

  orderBook: PerpsDataChannel<OrderBookData | null>;

  /**
   * Server-aggregated order book, fed by a second, independent subscription
   * that uses `nSigFigs`/`mantissa`. Kept separate from `orderBook` so the raw,
   * full-precision channel (top-of-book mid, slippage) is never coarsened by
   * the order-book panel's grouping.
   */
  orderBookAggregated: PerpsDataChannel<OrderBookData | null>;

  /**
   * Health of the dedicated aggregated order-book socket. Lets the order-book
   * panel surface a reconnect affordance when its connection drops without
   * disturbing the raw channel or the rest of the perps UI.
   */
  orderBookAggregatedStatus: PerpsDataChannel<OrderBookConnectionStatus>;

  // Candle stream channel (multiplexed by symbol+interval)
  candles: CandleStreamChannel;

  // Internal state
  private prewarmCleanups: (() => void)[] = [];

  // Tracks which address this manager is initialized for
  private initializedAddress: string | null = null;

  // Timestamp of the most recent background stream update (any channel).
  private _lastStreamUpdateAt = 0;

  private liveMarkets = new WeakSet<PerpsMarketData>();

  private livePrices: readonly PriceUpdate[] | null = null;

  private initializationQueue: Promise<void> = Promise.resolve();

  private initializationGeneration = 0;

  private preloadId: string | null = null;

  /**
   * UI-owned identity for the active aggregated order-book subscription.
   * Background emissions whose `subscriptionId` does not match are discarded so
   * a stale packet from a prior grouping cannot repopulate the cleared channel
   * during the async deactivate/activate IPC gap.
   */
  private activeOrderBookAggregatedSubscriptionId: string | null = null;

  // Deduplicates concurrent initForAddress calls
  private pendingInit: {
    address: string;
    promise: Promise<void>;
    acceptsUpdates: boolean;
  } | null = null;

  // Optimistic overrides for TP/SL - preserves user-set values until WebSocket catches up
  private readonly optimisticTPSLOverrides: Map<
    string,
    OptimisticTPSLOverride
  > = new Map();

  // When we last set an optimistic update - used to block WebSocket overwrites
  private lastOptimisticUpdateTime = 0;

  private _useTerminalApi = false;

  constructor() {
    this.positions = new PerpsDataChannel<Position[]>({
      connectFn: (push) => {
        let cancelled = false;
        const timer = setTimeout(() => {
          if (cancelled || this.positions.hasCachedData()) {
            return;
          }
          submitRequestToBackground<Position[]>('perpsGetPositions', [])
            .then((data) => {
              if (!cancelled && !this.positions.hasCachedData()) {
                push(data ?? EMPTY_POSITIONS);
              }
            })
            .catch((err) => {
              console.error(
                '[PerpsStreamManager] Failed to fetch positions',
                err,
              );
              if (!cancelled && !this.positions.hasCachedData()) {
                push(EMPTY_POSITIONS);
              }
            });
        }, WS_GRACE_PERIOD_MS);

        return () => {
          cancelled = true;
          clearTimeout(timer);
        };
      },
      initialValue: EMPTY_POSITIONS,
      name: 'positions',
    });

    this.orders = new PerpsDataChannel<Order[]>({
      connectFn: (push) => {
        let cancelled = false;
        const timer = setTimeout(() => {
          if (cancelled || this.orders.hasCachedData()) {
            return;
          }
          submitRequestToBackground<Order[]>('perpsGetOpenOrders', [])
            .then((data) => {
              if (!cancelled && !this.orders.hasCachedData()) {
                push(data ?? EMPTY_ORDERS);
              }
            })
            .catch((err) => {
              console.error('[PerpsStreamManager] Failed to fetch orders', err);
              if (!cancelled && !this.orders.hasCachedData()) {
                push(EMPTY_ORDERS);
              }
            });
        }, WS_GRACE_PERIOD_MS);

        return () => {
          cancelled = true;
          clearTimeout(timer);
        };
      },
      initialValue: EMPTY_ORDERS,
      name: 'orders',
    });

    this.account = new PerpsDataChannel<AccountState | null>({
      connectFn: (push) => {
        let cancelled = false;
        const timer = setTimeout(() => {
          if (cancelled || this.account.hasCachedData()) {
            return;
          }
          submitRequestToBackground<AccountState>('perpsGetAccountState', [])
            .then((data) => {
              // An empty resolution is not account data either — pushing the
              // channel's own `null` initialValue notifies subscribers without
              // setting a cache, which is the same fabricated `$0.00` as the
              // rejection path below.
              if (!cancelled && data && !this.account.hasCachedData()) {
                push(data);
              }
            })
            .catch((err) => {
              console.error(
                '[PerpsStreamManager] Failed to fetch account',
                err,
              );
              // Deliberately do NOT push here. `null` is this channel's own
              // initialValue, so pushing it leaves hasCachedData() false while
              // still notifying subscribers — usePerpsChannel then clears
              // isInitialLoading and the balance header renders the failure as
              // a settled `$0.00`, hiding Withdraw on a funded account. Staying
              // silent keeps the skeleton up until real data arrives from the
              // WebSocket or a later fetch.
            });
        }, WS_GRACE_PERIOD_MS);

        return () => {
          cancelled = true;
          clearTimeout(timer);
        };
      },
      initialValue: null,
      name: 'account',
    });

    this.markets = new PerpsDataChannel<PerpsMarketData[]>({
      connectFn: (push) => {
        let cancelled = false;
        const timer = setTimeout(() => {
          if (cancelled || this.markets.hasCachedData()) {
            return;
          }
          submitRequestToBackground<PerpsMarketData[]>(
            'perpsGetMarketDataWithPrices',
            [{ useTerminalApi: this._useTerminalApi }],
          )
            .then((data) => {
              if (!cancelled && !this.markets.hasCachedData()) {
                this.pushLiveMarkets(data ?? EMPTY_MARKETS);
              }
            })
            .catch((err) => {
              if (cancelled) {
                return;
              }
              console.error(
                '[PerpsStreamManager] Failed to fetch markets',
                err,
              );
              if (!this.markets.hasCachedData()) {
                push(EMPTY_MARKETS);
              }
            });
        }, WS_GRACE_PERIOD_MS);

        return () => {
          cancelled = true;
          clearTimeout(timer);
        };
      },
      initialValue: EMPTY_MARKETS,
      name: 'markets',
    });

    this.prices = new PerpsDataChannel<PriceUpdate[]>({
      connectFn: placeholderConnectFn,
      initialValue: EMPTY_PRICES,
      name: 'prices',
    });

    this.orderBook = new PerpsDataChannel<OrderBookData | null>({
      connectFn: placeholderConnectFn,
      initialValue: null,
      name: 'orderBook',
    });

    this.orderBookAggregated = new PerpsDataChannel<OrderBookData | null>({
      connectFn: placeholderConnectFn,
      initialValue: null,
      name: 'orderBookAggregated',
    });

    this.orderBookAggregatedStatus =
      new PerpsDataChannel<OrderBookConnectionStatus>({
        connectFn: placeholderConnectFn,
        initialValue: 'connecting',
        name: 'orderBookAggregatedStatus',
      });

    this.fills = new PerpsDataChannel<OrderFill[]>({
      connectFn: placeholderConnectFn,
      initialValue: EMPTY_FILLS,
      name: 'fills',
    });

    this.candles = new CandleStreamChannel();
  }

  /**
   * Returns the timestamp of the last background stream update.
   * Returns 0 if no update has been received yet.
   */
  getLastStreamUpdateAt(): number {
    return this._lastStreamUpdateAt;
  }

  /**
   * Register the UI identity for the active aggregated order-book stream.
   * Call synchronously when a subscription instance starts, and pass `null` on
   * unmount / teardown so late packets are rejected until the next activation.
   *
   * @param subscriptionId - Active instance identity, or `null` when no
   * aggregated subscription is live.
   */
  setActiveOrderBookAggregatedSubscriptionId(
    subscriptionId: string | null,
  ): void {
    this.activeOrderBookAggregatedSubscriptionId = subscriptionId;
  }

  /**
   * Update whether REST fallback calls for market data should route through
   * the MetaMask Terminal API.  Called from the UI layer whenever the
   * `perpsTerminalBackendEnabled` remote feature flag changes.
   *
   * @param enabled - true to pass `useTerminalApi: true` on market REST calls
   */
  setUseTerminalApi(enabled: boolean): void {
    if (this._useTerminalApi === enabled) {
      return;
    }
    this._useTerminalApi = enabled;
    // The markets channel may already hold data fetched under the previous
    // mode (direct-provider vs Terminal-enriched). Drop it so the next
    // subscribe re-fetches through the correct backend instead of serving
    // stale-mode data — otherwise a false→true flip could leave un-enriched
    // direct markets cached and suppress the Terminal REST fallback.
    this.markets.clearCache();
    this.liveMarkets = new WeakSet<PerpsMarketData>();
  }

  /**
   * Set optimistic TP/SL override for a position.
   * This preserves user-set values when WebSocket sends stale data.
   *
   * @param symbol - Position symbol
   * @param takeProfitPrice - Take profit price (or undefined to clear)
   * @param stopLossPrice - Stop loss price (or undefined to clear)
   */
  setOptimisticTPSL(
    symbol: string,
    takeProfitPrice?: string,
    stopLossPrice?: string,
  ): void {
    this.lastOptimisticUpdateTime = Date.now();
    this.optimisticTPSLOverrides.set(symbol, {
      takeProfitPrice,
      stopLossPrice,
      expiresAt: Date.now() + OPTIMISTIC_OVERRIDE_TTL_MS,
    });
  }

  /**
   * Clear optimistic override for a position.
   *
   * @param symbol - Position symbol
   */
  clearOptimisticTPSL(symbol: string): void {
    this.optimisticTPSLOverrides.delete(symbol);
  }

  /**
   * Clears all optimistic TP/SL overrides (e.g. after closing every position).
   */
  clearAllOptimisticTPSL(): void {
    this.optimisticTPSLOverrides.clear();
  }

  /**
   * Push positions to the channel with optimistic overrides applied.
   * Use this instead of positions.pushData() when pushing data from REST
   * (delayed refetch, visibility refetch) so we don't overwrite with stale
   * data while the override is active.
   *
   * IMPORTANT: We do NOT clear overrides when merging REST data - only clear
   * when WebSocket confirms. Otherwise REST could return correct data, we'd
   * clear the override, then the next WebSocket push (still stale) would
   * overwrite with old values.
   *
   * @param positions - Raw positions from REST
   */
  pushPositionsWithOverrides(positions: Position[]): void {
    const withOverrides = this.applyOptimisticOverrides(positions, false);
    this.positions.pushData(withOverrides);
  }

  /**
   * Apply optimistic overrides to positions array.
   * Expired overrides are automatically cleaned up.
   *
   * @param positions - Raw positions from stream
   * @param clearOnMatch - If true, clear override when incoming matches expected. Only true for WebSocket data.
   * @returns Positions with active optimistic overrides merged in
   */
  private applyOptimisticOverrides(
    positions: Position[],
    clearOnMatch = true,
  ): Position[] {
    const now = Date.now();

    // Clean up expired overrides
    for (const [symbol, override] of this.optimisticTPSLOverrides.entries()) {
      if (override.expiresAt < now) {
        this.optimisticTPSLOverrides.delete(symbol);
      }
    }

    // If no active overrides, return as-is
    if (this.optimisticTPSLOverrides.size === 0) {
      return positions;
    }

    return positions.map((position) => {
      const override = this.optimisticTPSLOverrides.get(position.symbol);
      if (override) {
        if (clearOnMatch) {
          const incomingTp = position.takeProfitPrice ?? '';
          const incomingSl = position.stopLossPrice ?? '';
          const expectedTp = override.takeProfitPrice ?? '';
          const expectedSl = override.stopLossPrice ?? '';
          const tpMatches =
            incomingTp === expectedTp ||
            (incomingTp &&
              expectedTp &&
              Number.parseFloat(incomingTp) === Number.parseFloat(expectedTp));
          const slMatches =
            incomingSl === expectedSl ||
            (incomingSl &&
              expectedSl &&
              Number.parseFloat(incomingSl) === Number.parseFloat(expectedSl));

          if (tpMatches && slMatches) {
            this.optimisticTPSLOverrides.delete(position.symbol);
            return position;
          }
        }

        return {
          ...position,
          takeProfitPrice: override.takeProfitPrice,
          stopLossPrice: override.stopLossPrice,
        };
      }
      return position;
    });
  }

  /**
   * Initialize the stream manager for a specific address.
   * All stream data arrives via background notifications —
   * no UI controller is created. This records the address and
   * clears caches when the address changes.
   *
   * View activation signaling (perpsViewActive) is handled by PerpsLayout,
   * not here.
   *
   * @param address - The selected account address
   */
  init(address: string): void {
    if (!address) {
      console.warn('[PerpsStreamManager] No address provided');
      return;
    }

    const currentControllerAddress = this.initializedAddress;

    // If same address and already initialized, nothing to do
    if (currentControllerAddress === address) {
      return;
    }

    // Address changed - fully reset channels so they disconnect and
    // re-fetch data for the new account on next subscribe.
    if (currentControllerAddress !== null) {
      this.cleanupPrewarm();
      this.positions.reset();
      this.orders.reset();
      this.account.reset();
      this.fills.reset();
      this.markets.reset();
      this.prices.reset();
      this.orderBook.reset();
      this.orderBookAggregated.reset();
      this.orderBookAggregatedStatus.reset();
      this.candles.clearAll();
      this.optimisticTPSLOverrides.clear();
      this._lastStreamUpdateAt = 0;
      clearPerpsMarketInfoModuleCache();
      clearPerpsMarketFillsModuleCache();
      clearAllCoalescedRequests();
    }

    this.initializedAddress = address;
  }

  /**
   * Initialize the stream manager for a given address, including the
   * background `perpsInit` RPC call. Deduplicates concurrent calls so
   * that multiple hooks sharing this singleton only trigger one round-trip.
   *
   * @param address - The selected account address
   * @returns Resolves when the manager is ready for `address`, or rejects on error.
   */
  async initForAddress(address: string): Promise<void> {
    if (!address) {
      throw new Error('No account selected');
    }

    if (this.initializedAddress === address) {
      return;
    }

    // If there's already a pending init for this exact address, piggyback on it.
    if (this.pendingInit?.address === address) {
      await this.pendingInit.promise;
      return;
    }

    // Cancel old REST fallbacks while retaining mounted market subscriptions.
    this.reset(true);
    const generation = this.initializationGeneration;

    // Serialize account transitions so A → B → A cannot finish an older init
    // after the newest one and disconnect its provider.
    const promise = this.initializationQueue
      .catch(() => undefined)
      .then(async () => {
        if (generation !== this.initializationGeneration) {
          return;
        }
        try {
          // The shared background coordinator serializes provider teardown and
          // activation across windows. It emits snapshots before the RPC returns.
          await submitRequestToBackground('perpsInitForAccount', [address]);
          if (generation === this.initializationGeneration) {
            this.init(address);
          }
        } catch (error) {
          if (generation === this.initializationGeneration) {
            this.reset();
          }
          throw error;
        } finally {
          if (generation === this.initializationGeneration) {
            this.pendingInit = null;
          }
        }
      });
    this.pendingInit = { address, promise, acceptsUpdates: false };
    this.initializationQueue = promise;
    await promise;
  }

  /**
   * Handle a background stream notification for any channel.
   * Called from ui/index.js when a perpsStreamUpdate notification arrives.
   *
   * @param payload - The notification payload
   * @param payload.channel - Which channel the data is for
   * @param payload.data - The raw data payload
   * @param payload.symbol - For candles: the asset symbol
   * @param payload.interval - For candles: the candle period
   * @param payload.subscriptionId - For aggregated order book: UI identity
   * @param payload.live - Whether market metadata was fetched in this session.
   */
  handleBackgroundUpdate(payload: {
    channel: string;
    data: unknown;
    symbol?: string;
    interval?: CandlePeriod;
    subscriptionId?: string;
    live?: boolean;
  }): void {
    if (payload.channel === 'accountSession') {
      const session = payload.data as { address?: string };
      if (
        this.pendingInit &&
        session.address?.toLowerCase() ===
          this.pendingInit.address.toLowerCase()
      ) {
        this.pendingInit.acceptsUpdates = true;
      }
      return;
    }
    if (this.pendingInit?.acceptsUpdates === false) {
      return;
    }
    this._lastStreamUpdateAt = Date.now();
    const { channel, data } = payload;
    switch (channel) {
      case 'positions': {
        const positions = data as Position[];
        const now = Date.now();
        const inBlockPeriod =
          now - this.lastOptimisticUpdateTime < WEBSOCKET_BLOCK_MS;
        if (inBlockPeriod && this.optimisticTPSLOverrides.size > 0) {
          return;
        }
        const withOverrides = this.applyOptimisticOverrides(positions);
        this.positions.pushData(withOverrides);
        break;
      }
      case 'orders':
        this.orders.pushData(data as Order[]);
        break;
      case 'account': {
        const acc = data as AccountState | null;
        this.account.pushData(acc);
        break;
      }
      case 'fills':
        this.fills.pushData(data as OrderFill[]);
        break;
      case 'prices': {
        // Wallet preload and the foreground symbol stream share this cache.
        // A detail update must not discard the other preloaded market prices.
        const prices = new Map(
          this.prices.getCachedData().map((price) => [price.symbol, price]),
        );
        (data as PriceUpdate[]).forEach((price) =>
          prices.set(price.symbol, price),
        );
        const snapshot = Array.from(prices.values());
        this.livePrices = snapshot;
        this.prices.pushData(snapshot);
        break;
      }
      case 'orderBook':
        this.orderBook.pushData(data as OrderBookData);
        break;
      case 'orderBookAggregated':
        if (
          !this.isActiveOrderBookAggregatedSubscription(payload.subscriptionId)
        ) {
          return;
        }
        this.orderBookAggregated.pushData(data as OrderBookData);
        break;
      case 'orderBookAggregatedStatus':
        if (
          !this.isActiveOrderBookAggregatedSubscription(payload.subscriptionId)
        ) {
          return;
        }
        this.orderBookAggregatedStatus.pushData(
          data as OrderBookConnectionStatus,
        );
        break;
      case 'candles': {
        const { symbol, interval } = payload;
        if (symbol && interval) {
          this.candles.pushFromBackground({
            symbol,
            interval,
            data: data as CandleData,
          });
        }
        break;
      }
      case 'markets':
        if (payload.live) {
          this.pushLiveMarkets(data as PerpsMarketData[]);
        } else {
          this.markets.pushData(data as PerpsMarketData[]);
        }
        break;
      case 'connectionState':
        break;
      default:
        console.warn('[PerpsStreamManager] Unknown channel:', channel);
    }
  }

  /**
   * Whether an aggregated order-book emission matches the UI's active identity.
   * When no active identity is registered (panel closed / between activations),
   * every aggregated packet is rejected so a late emission cannot refill the
   * cache. While a subscription is active, only matching `subscriptionId`s
   * are accepted.
   *
   * @param subscriptionId - Identity tagged on the background emission.
   * @returns True when the packet may update the aggregated channels.
   */
  private isActiveOrderBookAggregatedSubscription(
    subscriptionId: string | undefined,
  ): boolean {
    const activeId = this.activeOrderBookAggregatedSubscriptionId;
    if (activeId === null) {
      return false;
    }
    return subscriptionId === activeId;
  }

  /**
   * Record fresh market metadata separately from persisted cache hydration.
   *
   * @param markets - Markets fetched for the current connection and backend.
   */
  pushLiveMarkets(markets: PerpsMarketData[]): void {
    this.liveMarkets = new WeakSet(markets);
    this.markets.pushData(markets);
  }

  /**
   * Distinguish the market snapshot read during render from a persisted seed.
   *
   * @param markets - Snapshot consumed by the market hook.
   * @returns Whether this is the current-session live snapshot.
   */
  hasLiveMarketData(markets: readonly PerpsMarketData[]): boolean {
    return markets.some((market) => this.liveMarkets.has(market));
  }

  /**
   * Check the actual price snapshot consumed during render.
   *
   * @param prices - Snapshot consumed by the price hook.
   * @returns Whether it contains a live positive price.
   */
  hasLivePrices(prices: readonly PriceUpdate[]): boolean {
    return (
      prices === this.livePrices &&
      prices.some((price) => Number(price.price) > 0)
    );
  }

  /**
   * Check if the stream manager has been initialized for a specific address.
   *
   * @param address - Optional address to check
   */
  isInitialized(address?: string): boolean {
    if (address) {
      return this.initializedAddress === address;
    }
    return this.initializedAddress !== null;
  }

  /**
   * Get the current address the manager is initialized for
   */
  getCurrentAddress(): string | null {
    return this.initializedAddress;
  }

  /**
   * Own a wallet preload until it is ready, released, or times out.
   * @param options - Account, market backend and requested transition.
   * @param options.address
   * @param options.useTerminalApi
   * @param options.accountChanged
   * @param options.provider - Perps provider this preload is for.
   * @param options.isTestnet - Network this preload is for.
   * @returns A handle that releases this preload.
   */
  startPreload({
    address,
    useTerminalApi,
    accountChanged,
    provider,
    isTestnet,
  }: {
    address: string;
    useTerminalApi: boolean;
    accountChanged: boolean;
    provider: string;
    isTestnet: boolean;
  }): { stop: () => void } {
    const name = accountChanged
      ? TraceName.PerpsAccountSwitchReconnection
      : TraceName.PerpsConnectionEstablishment;
    this.setUseTerminalApi(useTerminalApi);
    const id = crypto.randomUUID();
    this.preloadId = id;
    let generation = this.initializationGeneration;
    const isCurrent = () =>
      this.preloadId === id && generation === this.initializationGeneration;
    const invalidateReadiness = () => {
      if (isCurrent()) {
        // Retire readiness without cancelling mounted streams or REST fallbacks.
        // Late initialization must not restore readiness after preload is released.
        this.initializationGeneration += 1;
        this.pendingInit = null;
        this.initializedAddress = null;
        this.cleanupPrewarm();
      }
    };
    let cancelled = false;
    let ended = false;
    let preloadReady = false;
    const release = (preserveConnection = false) => {
      submitRequestToBackground('perpsStopPreload', [
        id,
        preserveConnection,
      ]).catch((error: unknown) => {
        console.debug('[PerpsStreamManager] Release failed', error);
      });
    };
    try {
      trace({
        name,
        id,
        op: TraceOperation.PerpsOperation,
        tags: {
          feature: 'perps',
          [PERPS_LIFECYCLE_TAG]: readPerpsLifecycleContext(),
          source: 'wallet_root',
          provider,
          [TESTNET_TAG]: isTestnet,
          [START_BOUNDARY_TAG]: 'wallet_root_effect',
          [COMPLETION_BOUNDARY_TAG]: 'preload_ready',
          ...(accountChanged ? { trigger: 'requested_account_change' } : {}),
        },
      });
    } catch (error) {
      console.debug('[PerpsStreamManager] Trace start failed', error);
    }
    const finish = (success: boolean, reason: PreloadEndReason) => {
      if (ended) {
        return;
      }
      ended = true;
      const timestamp = getPerformanceTimestamp();
      try {
        endTrace({
          timestamp,
          name,
          id,
          data: { success, reason },
        });
      } catch (error) {
        console.debug('[PerpsStreamManager] Trace end failed', error);
      }
    };
    const timeout = setTimeout(() => {
      cancelled = true;
      finish(false, 'timeout');
      release();
      invalidateReadiness();
    }, CONNECTION_TIMEOUT_MS);
    submitRequestToBackground('perpsRegisterPreload', [id])
      .then(async () => {
        if (!cancelled && isCurrent()) {
          const initialization = this.initForAddress(address);
          generation = this.initializationGeneration;
          await initialization;
        }
      })
      .then(async () => {
        if (cancelled || !isCurrent()) {
          return;
        }
        this.prewarm();
        await submitRequestToBackground('perpsStartPreload', [id]);
        if (!cancelled) {
          preloadReady = true;
          finish(true, 'subscriptions_ready');
        }
      })
      .catch((error: unknown) => {
        finish(false, 'connection_failed');
        if (!cancelled) {
          release();
          invalidateReadiness();
          console.debug('[PerpsStreamManager] Preload failed', error);
        }
      })
      .finally(() => clearTimeout(timeout));

    return {
      stop: () => {
        cancelled = true;
        clearTimeout(timeout);
        finish(false, 'released');
        // Successful preload leaves provider teardown to the last-UI grace period.
        release(preloadReady);
        if (isCurrent()) {
          this.cleanupPrewarm();
        }
      },
    };
  }

  /**
   * Prewarm all channels - start subscriptions to keep cache fresh.
   * Call this when entering Perps (tab or any route).
   */
  prewarm(): void {
    if (this.prewarmCleanups.length > 0) {
      // Already prewarming
      return;
    }

    this.prewarmCleanups = [
      this.positions.prewarm(),
      this.orders.prewarm(),
      this.account.prewarm(),
      this.markets.prewarm(),
      this.prices.prewarm(),
      this.orderBook.prewarm(),
    ];
  }

  /**
   * Stop prewarming - cleanup long-lived subscriptions.
   * Call this when leaving Perps entirely.
   * Note: Cache is NOT cleared, only subscriptions are cleaned up.
   */
  cleanupPrewarm(): void {
    if (this.prewarmCleanups.length === 0) {
      return;
    }

    this.prewarmCleanups.forEach((cleanup) => cleanup());
    this.prewarmCleanups = [];
  }

  /**
   * Check if currently prewarming
   */
  isPrewarming(): boolean {
    return this.prewarmCleanups.length > 0;
  }

  /**
   * Clear all channel caches.
   * Called on account/network change.
   */
  clearAllCaches(): void {
    this.liveMarkets = new WeakSet<PerpsMarketData>();
    this.livePrices = null;
    this.positions.clearCache();
    this.orders.clearCache();
    this.account.clearCache();
    this.fills.clearCache();
    this.markets.clearCache();
    this.prices.clearCache();
    this.orderBook.clearCache();
    this.orderBookAggregated.clearCache();
    this.orderBookAggregatedStatus.clearCache();
    this.candles.clearCache();
    this._lastStreamUpdateAt = 0;
    clearPerpsMarketInfoModuleCache();
    clearPerpsMarketFillsModuleCache();
    clearAllCoalescedRequests();
  }

  /**
   * Full reset - clear caches and reset channel state.
   * Called on account switch or when leaving Perps entirely.
   * Note: Does not reset address tracking (handled by this.initializedAddress).
   * @param preserveMarketSubscriptions
   */
  reset(preserveMarketSubscriptions = false): void {
    this.initializationGeneration += 1;
    this.pendingInit = null;
    this.liveMarkets = new WeakSet<PerpsMarketData>();
    this.livePrices = null;
    this.cleanupPrewarm();
    this.positions.reset();
    this.orders.reset();
    this.account.reset();
    this.fills.reset();
    this.markets.reset();
    this.prices.reset();
    this.orderBook.reset();
    this.orderBookAggregated.reset();
    this.orderBookAggregatedStatus.reset();
    if (preserveMarketSubscriptions) {
      this.candles.clearCache();
    } else {
      this.candles.clearAll();
    }
    this.optimisticTPSLOverrides.clear();
    this.initializedAddress = null;
    this._lastStreamUpdateAt = 0;
    clearPerpsMarketInfoModuleCache();
    clearPerpsMarketFillsModuleCache();
    clearAllCoalescedRequests();
  }

  /**
   * Seed the per-channel caches from the background controller's persisted
   * snapshots so a fresh popup mount renders real data on its first frame
   * instead of a skeleton. Existing cache is left untouched — the first
   * push from the live stream wins over the persisted snapshot.
   *
   * User-scoped channels (positions/orders/account) are only hydrated when
   * the snapshot's owning address matches the account the manager is being
   * initialised for, so an account switch while the popup is closed does
   * not paint the old account's data under the new account's identity.
   *
   * Empty arrays intentionally no-op: pushing an empty array would flip
   * `hasCachedData()` to true (since the pushed reference differs from
   * `initialValue`) and suppress the WS-grace REST fallback in each
   * channel's `connectFn`.
   *
   * @param snapshot - Controller caches for the active provider + network.
   * @param snapshot.markets - Cached `PerpsMarketData[]` (provider-scoped).
   * @param snapshot.positions - Cached positions for `snapshot.address`.
   * @param snapshot.orders - Cached orders for `snapshot.address`.
   * @param snapshot.account - Cached `AccountState` for `snapshot.address`.
   * @param snapshot.address - Address that owns the user-scoped entries. User channels are skipped unless this matches the currently selected address. Pass `null` to hydrate nothing user-scoped.
   * @param selectedAddress - Address the caller considers active; must equal `snapshot.address` for user channels to hydrate.
   */
  hydrateFromControllerCache(
    snapshot: {
      markets?: PerpsMarketData[] | null;
      positions?: Position[] | null;
      orders?: Order[] | null;
      account?: AccountState | null;
      address?: string | null;
    },
    selectedAddress?: string | null,
  ): void {
    if (snapshot.markets?.length && !this.markets.hasCachedData()) {
      this.markets.pushData(snapshot.markets);
    }

    const snapshotAddress = snapshot.address;
    if (
      !selectedAddress ||
      !snapshotAddress ||
      snapshotAddress.toLowerCase() !== selectedAddress.toLowerCase()
    ) {
      return;
    }

    if (snapshot.positions?.length && !this.positions.hasCachedData()) {
      this.positions.pushData(snapshot.positions);
    }
    if (snapshot.orders?.length && !this.orders.hasCachedData()) {
      this.orders.pushData(snapshot.orders);
    }
    if (snapshot.account && !this.account.hasCachedData()) {
      this.account.pushData(snapshot.account);
    }
  }
}

// Module-level singleton instance
const streamManager = new PerpsStreamManager();

/**
 * Get the PerpsStreamManager singleton instance.
 * This is shared across all Perps views.
 */
export function getPerpsStreamManager(): PerpsStreamManager {
  return streamManager;
}

/**
 * Reset the stream manager (for testing or account switch).
 */
export function resetPerpsStreamManager(): void {
  streamManager.reset();
}

export { PerpsStreamManager };
